  function finalizeCockpitNavigation(){["scienceEarthBack","journalBack","storageBack"].forEach(id=>{const button=$(id);if(button){button.textContent="← Cockpit";button.onclick=openCockpit}});const pilotButton=$("cockpitPilotInfo");if(pilotButton){pilotButton.textContent="Change pilot · 1 Knowledge Gem";pilotButton.onclick=()=>{state.gemWorkshop.focus="pilot";state.screen="storage";save();render()}}const hotspots=document.querySelector(".cockpit-hotspots");if(hotspots&&!$("cockpitZodiac")){const zodiac=window.ZodiacMap?.ensureState(state)||state.zodiac,button=document.createElement("button");button.className="cockpit-hotspot zodiac";button.id="cockpitZodiac";button.setAttribute("aria-label","Zodiac star atlas");button.innerHTML=`<span>Zodiac star atlas</span><small>${zodiac.fragments.length}/20 pieces · ${zodiac.totalCorrect}/60 answers</small>`;button.onclick=()=>showCockpitInfo({icon:"✦",kicker:"LEFT HOLOGRAPHIC GLASS",title:"Zodiac Star Atlas",text:"Build the celestial chart by solving new Math questions. Every three correct answers unlocks a star or element.",meta:`${zodiac.fragments.length}/20 pieces · ${zodiac.totalCorrect}/60 answers`,actionLabel:"Open Zodiac Atlas →",onAction:()=>{state.screen="zodiac";save();render()}});hotspots.appendChild(button)}}
  function refreshScienceCounts(){if(state.screen!=="earthHub")return;const days=Object.values(state.science.completedByWeek||{}).reduce((sum,list)=>sum+(Array.isArray(list)?list.length:0),0),research=document.querySelector(".earth-path-card.research"),journal=document.querySelector(".earth-path-card.vocabulary");if(research){const description=research.querySelector("p:not(.adventure-kicker)"),stats=research.querySelectorAll(".path-meta b");if(description)description.textContent=`Choose among ${SCIENCE_WEEK_COUNT} complete science weeks and follow each story at your own pace.`;if(stats[0])stats[0].textContent=`${days}/${SCIENCE_TOTAL_DAYS} science days`}if(journal){const stats=journal.querySelectorAll(".path-meta b");if(stats[0])stats[0].textContent=`${SCIENCE_WEEK_COUNT} weekly collections`}}
