  function renderBrief(){const b=briefing[state.brief]||briefing.earthReady,complete=/Complete|rescued|complete/i.test(b.questions+b.title),travel=/Travel|comet/.test(state.brief),energy=travel?`Ship ${state.ship.hp} HP · ${state.ship.shield} Shield`:`Explorer ${state.human.hp} HP · ${state.human.shield} Shield`;VIEW.innerHTML=`<section class="mission-brief"><article class="mission-brief-card"><p class="adventure-kicker">MISSION BRIEFING</p><h1>${b.title}</h1><p>${b.desc}</p><div class="brief-grid"><article><small>Challenge</small><strong>${b.questions}</strong></article><article><small>Reward</small><strong>${b.reward}</strong></article><article><small>Risk</small><strong>${b.danger}</strong></article><article><small>Current energy</small><strong>${energy}</strong></article><article><small>Question pool</small><strong>No repeats</strong></article></div><div class="guide-box"><strong>How to play</strong><br>Answer in English. Hint or Translate costs 1 Shield; if Shield is empty, it costs 1 HP. Every correct answer restores 1 Shield. Every third correct answer restores 1 HP.</div><div class="mission-actions"><button class="secondary-space-button" id="briefBack">← Solar map</button>${complete?"":`<button class="primary-space-button" id="launchMission">Launch mission →</button>`}</div></article></section>`;$("briefBack").onclick=()=>{state.screen="map";save();render()};if($("launchMission"))$("launchMission").onclick=launchBriefMission}
  function launchBriefMission(){const kind=state.brief;if(kind==="earthReady"||kind.endsWith("Complete")){state.screen="map";return render()}if(kind==="moonBoss"){state.screen="bossIntro";state.boss.currentId="";save();return render()}const totals={earthParts:10,moonTravel:5,moonPrep:10,marsTravel:5,marsSurvey:25,comet:3,ore:5};startMission(kind,totals[kind])}
  function startMission(kind,total){const travel=/Travel|comet/.test(kind),done=kind==="earthParts"?Math.min(state.shipParts,total):0;state.mission={kind,total,done,currentId:"",travel,notice:""};if(travel&&Math.random()<.5){const loss=Math.floor(Math.random()*5)+1;state.ship.shield=Math.max(0,state.ship.shield-loss);state.mission.notice=`Meteor storm! The ship lost ${loss} Shield.`}state.screen="mission";save();nextMissionQuestion()}
